   parsers: {
     babel,
     "babel-flow": babelFlow,
     "babel-ts": babelTypeScript,
     json: {
       ...babelExpression,
       hasPragma() {
         return true;
       },
     },
     json5: babelExpression,
     "json-stringify": {
       parse: parseJson,
       astFormat: "estree-json",
       ...locFns,
     },
